import{_ as e,o as l,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-11-27 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-11-27 :: Ceph Orchestration Meeting","date":"2019-11-27T00:00:00.000Z","updated":"2019-11-28T00:00:00.000Z","tags":["Ceph","分布式存储","Ceph Orchestrator","性能问题","线程池","parallel SSH","pssh","Dashboard"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-27_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-11-27_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),a={name:"posts/2019/2019-11-27_-_-_Ceph_Orchestration_Meeting.md"};function i(o,t,n,p,h,_){return l(),r("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>日期：</strong> 2019-11-27</p><p><strong>参会人员：</strong> Sebastian, Keifa, 以及其他相关人员</p><p><strong>会议目的：</strong> 讨论Ceph Orchestrator的性能问题及后续行动计划。</p><p><strong>主要议题及讨论内容：</strong></p><ol><li><p><strong>会议时间调整：</strong></p><ul><li>由于Paul无法参加晚间会议，Sebastian提出调整会议时间或取消。</li><li>会议决定取消当前会议，后续会议将在Sebastian休假回来后重新安排。</li></ul></li><li><p><strong>Ceph Orchestrator性能问题：</strong></p><ul><li>当前Orchestrator使用单线程池（kernel threads）处理后台操作，导致性能受限。</li><li>讨论了三个主要的使用案例：部署OSD、设备列表刷新（device ls refresh）和服务列表刷新（service ls refresh）。</li><li>提出增加线程池数量至10以提升性能，但仍存在局限性。</li><li>探讨了使用parallel SSH或pssh工具来并行处理多个主机上的操作，以提高效率。</li></ul></li><li><p><strong>GitHub浏览技巧：</strong></p><ul><li>分享了在GitHub上快速查找文件的技巧，通过输入“T”并搜索文件名。</li></ul></li><li><p><strong>Dashboard更新：</strong></p><ul><li>OSD创建的相关Pia已获批准，等待QA测试。</li><li>讨论了预览功能的进展。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>取消当前会议，直至Sebastian休假回来。</li><li>研究使用parallel SSH或pssh工具来解决Orchestrator的性能问题。</li><li>继续推进Dashboard的更新和预览功能。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>Sebastian休假期间，团队将通过Dashboard stand-up进行同步。</li><li>研究并评估parallel SSH或pssh工具的可行性，并考虑维护或采用现有项目。</li></ul><p><strong>其他事项：</strong></p><ul><li>Sebastian休假期间，团队成员需自行处理升级等相关事宜。</li><li>会议结束时，Sebastian祝愿大家假期愉快，并感谢大家的努力。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议在Sebastian的祝福中结束，Keifa和其他成员也表达了良好的祝愿。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的技术术语和工具如“kernel threads”、“parallel SSH”、“pssh”等，是计算机科学和Ceph分布式存储领域的关键技术点。</li></ul>',16)])])}const c=e(a,[["render",i]]);export{u as __pageData,c as default};
